import type { ComponentProps, CSSProperties } from "react";
import { cn } from "./lib/cn";

const variants = {
  neutral: "bg-muted text-muted-foreground",
  info: "bg-brand-subtle text-[color-mix(in_srgb,var(--accent-text)_82%,var(--foreground))]",
  success: "bg-success-subtle text-success",
  warning: "bg-warning-subtle text-warning",
  error: "bg-destructive-subtle text-destructive",
};

/* Status survives without colour: each variant has its own shape. */
const shapes = {
  neutral: <path d="M2 5h6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />,
  info: <circle cx="5" cy="5" r="3.6" fill="none" stroke="currentColor" strokeWidth="1.6" />,
  success: <circle cx="5" cy="5" r="4" fill="currentColor" />,
  warning: (
    <>
      <path d="M5 1a4 4 0 0 1 0 8z" fill="currentColor" />
      <circle cx="5" cy="5" r="4" fill="none" stroke="currentColor" strokeWidth="1.6" />
    </>
  ),
  error: <path d="M2 2l6 6M8 2 2 8" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />,
};

/* Categorical hues for labels that name a kind, not a status (a deal stage, a team, a type): OKLCH hue angles.
   Lightness and chroma come per theme from tokens.css (--tone-*), so the text holds 4.5:1 on its wash in both. */
export const toneHues = { blue: 255, violet: 295, rose: 2, orange: 50, amber: 82, green: 150, teal: 195, slate: 260 } as const;
export type BadgeTone = keyof typeof toneHues;

export type BadgeProps = ComponentProps<"span"> & {
  variant?: keyof typeof variants;
  /** A categorical hue with a dot, for kinds rather than statuses. Overrides the variant's colour. */
  tone?: BadgeTone;
  /** The status shape before the word. On for status variants, off for neutral labels and counts. */
  shape?: boolean;
};

export function Badge({
  className,
  variant = "neutral",
  tone,
  shape = variant !== "neutral" && !tone,
  children,
  style,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant}
      data-tone={tone}
      className={cn(
        "inline-flex h-[22px] shrink-0 items-center gap-1.5 whitespace-nowrap rounded-full px-2 text-xs leading-4 font-medium [&_svg]:size-3",
        (shape || tone) && "pl-[7px]",
        tone
          ? "bg-[oklch(var(--tone-bg-l)_var(--tone-bg-c)_var(--tone-h))] text-[oklch(var(--tone-fg-l)_var(--tone-fg-c)_var(--tone-h))]"
          : variants[variant],
        className,
      )}
      style={tone ? ({ "--tone-h": toneHues[tone], ...style } as CSSProperties) : style}
      {...props}
    >
      {tone && <span data-slot="badge-dot" aria-hidden="true" className="size-1.5 shrink-0 rounded-full bg-current" />}
      {shape && (
        <svg data-slot="badge-shape" viewBox="0 0 10 10" aria-hidden="true" className="!size-2.5">
          {shapes[variant]}
        </svg>
      )}
      {children}
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";
import { useRef, useState, type ComponentProps, type CSSProperties } from "react";
import { Badge, type BadgeTone } from "./badge";
import { cn } from "./lib/cn";
import "./tag-overflow.css";

export type OverflowTag = { label: string; tone?: BadgeTone };

export type TagOverflowProps = Omit<ComponentProps<"div">, "children"> & {
  /** Names the set, e.g. "Labels". */
  label: string;
  tags: (string | OverflowTag)[];
  /** Tags shown before the rest fold into a count. */
  max?: number;
};

/**
 * A row of tags that shows the first few and folds the rest into a "+N" count. Choosing the count opens the rest
 * one after another in place, and "Show less" folds them back, with focus kept on the toggle. For table cells,
 * cards and headers where tags must not take over. Under reduced motion the tags appear without the stagger.
 */
export function TagOverflow({ label, tags, max = 3, className, ...props }: TagOverflowProps) {
  const [open, setOpen] = useState(false);
  const [opened, setOpened] = useState(0); // counts openings, so the new tags replay their entrance each time
  const toggle = useRef<HTMLButtonElement>(null);
  const items = tags.map((tag) => (typeof tag === "string" ? { label: tag } : tag));
  const hidden = Math.max(0, items.length - max);
  const shown = open ? items : items.slice(0, max);

  return (
    <div role="group" aria-label={label} data-slot="tag-overflow" className={cn("flex flex-wrap items-center gap-1.5", className)} {...props}>
      {shown.map((tag, i) => (
        <Badge key={i >= max ? `${opened}-${i}` : i} tone={tag.tone} data-extra={i >= max ? "" : undefined} style={{ "--to-i": i - max } as CSSProperties}>
          {tag.label}
        </Badge>
      ))}
      {hidden > 0 && (
        <button
          ref={toggle}
          type="button"
          data-slot="to-toggle"
          aria-expanded={open}
          aria-label={open ? "Show fewer tags" : `Show ${hidden} more ${hidden === 1 ? "tag" : "tags"}`}
          onClick={() => {
            if (!open) setOpened((count) => count + 1);
            setOpen(!open);
          }}
        >
          {open ? "Show less" : `+${hidden}`}
        </button>
      )}
    </div>
  );
}

/* tag-overflow.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Tag overflow: extra tags pop in one after another; the count is a small pill. */
  [data-slot="tag-overflow"] [data-slot="badge"][data-extra] { animation: to-in 0.3s var(--ease-settle) calc(var(--to-i) * 45ms) backwards; }
  [data-slot="tag-overflow"] [data-slot="to-toggle"] { height: 22px; padding: 0 8px; border: 1px dashed var(--border-strong); border-radius: 999px; background: none; color: var(--muted-foreground); font-size: 12px; font-variant-numeric: tabular-nums; cursor: pointer; transition: color var(--duration-fast) var(--ease-out), border-color var(--duration-fast) var(--ease-out); }
  @media (hover: hover) { [data-slot="tag-overflow"] [data-slot="to-toggle"]:hover { color: var(--foreground); border-color: var(--foreground); } }
  [data-slot="tag-overflow"] [data-slot="to-toggle"]:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
  @media (prefers-reduced-motion: reduce) {
    [data-slot="tag-overflow"] [data-slot="badge"][data-extra] { animation: none; }
  }
  @keyframes to-in { from { opacity: 0; scale: 0.7; } }
}
